files.nginx.conf:
pid /state/home/nginx.pid;
error_log stderr;
events { worker_connections 512; }
http {
 access_log /dev/stdout;
 client_body_temp_path /state/home/client-temp;
 proxy_temp_path /state/home/proxy-temp;
 fastcgi_temp_path /state/home/fastcgi-temp;
 uwsgi_temp_path /state/home/uwsgi-temp;
 scgi_temp_path /state/home/scgi-temp;
 server { listen 8080; listen [::]:8080; location /health { return 200 "healthy\n"; } }
}
